from django.contrib import admin
from django.contrib.auth.models import User
from django.test import TestCase, override_settings
from django.urls import path, reverse

from .models import Article, Section

site = admin.AdminSite(name="custom_admin_site")


class ArticleReadonlyAdmin(admin.ModelAdmin):
    readonly_fields = ("section",)


site.register(Article, ArticleReadonlyAdmin)
site.register(Section)

urlpatterns = [
    path("custom-admin/", site.urls),
]


@override_settings(ROOT_URLCONF="admin_views.test_readonly_custom_site_repro")
class ReadonlyForeignKeyCustomSiteTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.user = User.objects.create_superuser("super", "super@example.com", "secret")

    def setUp(self):
        self.client.force_login(self.user)

    def test_readonly_fk_link_uses_custom_admin_prefix(self):
        section = Section.objects.create(name="Section")
        article = Article.objects.create(
            title="Article", content="Content", date="2020-01-01", section=section
        )
        url = reverse(
            "custom_admin_site:admin_views_article_change", args=[article.pk]
        )
        response = self.client.get(url)
        self.assertEqual(response.status_code, 200)
        expected = reverse(
            "custom_admin_site:admin_views_section_change",
            args=[section.pk],
        )
        self.assertContains(response, 'href="%s"' % expected)
        self.assertNotContains(response, 'href="/admin/admin_views/section/%s/change/"' % section.pk)
